const express = require("express");
const cors = require("cors");
const bodyParser = require("body-parser");
const fetch = require("node-fetch");

const app = express();
app.use(cors());
app.use(bodyParser.json());

app.post("/ask", async (req, res) => {
  const { prompt } = req.body;

  try {
    const response = await fetch("https://huggingface.co/spaces/yuntian-deng/ChatGPT/raw/main/app.py", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ inputs: prompt })
    });

    const data = await response.json();

    if (data && data.generated_text) {
      res.json({ answer: data.generated_text });
    } else {
      console.error("Unexpected response:", data);
      res.json({ answer: "🤖 No answer from chatbot." });
    }
  } catch (error) {
    console.error("Backend error:", error);
    res.status(500).json({ answer: "❌ Failed to get a response from chatbot." });
  }
});

app.listen(5000, () => {
  console.log("✅ Server running at http://localhost:5000");
});
